# Let me try swapping non-center symmetric pairs
input_grid = [
    [7, 0, 0, 0, 5],
    [0, 6, 0, 4, 0],
    [0, 0, 2, 0, 0],
    [0, 4, 0, 6, 0],
    [5, 0, 0, 0, 7]
]

# What if we swap corners with edge middles along each axis?
# Or what if we swap 7<->5 along main diagonal and 6<->4 along anti-diagonal?

def apply_swaps(grid):
    rows = len(grid)
    result = [row[:] for row in grid]  # copy
    # Swap 7s and 5s
    for r in range(rows):
        for c in range(rows):
            if grid[r][c] == 7:
                result[r][c] = 5
            elif grid[r][c] == 5:
                result[r][c] = 7
            elif grid[r][c] == 6:
                result[r][c] = 4
            elif grid[r][c] == 4:
                result[r][c] = 6
    return result

output1 = apply_swaps(input_grid)
print("\nSwapped 7<->5, 6<->4:")
for row in output1:
    print(row)

# What if only swap 7s and 5s?
def swap_only_corners(grid):
    rows = len(grid)
    result = [row[:] for row in grid]
    for r in range(rows):
        for c in range(rows):
            if grid[r][c] in [7, 5]:
                result[r][c] = 5 if grid[r][c] == 7 else 7
    return result

